    ctx = createTestContext();
  });

  afterEach(() => ctx.cleanup());

  it('returns the authenticated user', async () => {
    const registered = await request(ctx.app)
      .post('/api/auth/register')
      .send({ name: 'Ada', email: 'ada@example.com', password: 'sup3r-secret' })
      .expect(201);

