import type { Response } from 'express';
import type { ZodError, ZodType } from 'zod';
import { ValidationError } from './errors.js';

/**
 * Every successful response has the same shape:
 *   { "success": true, "data": <payload>, "meta": <optional> }
 *
 * and every failure:
 *   { "success": false, "error": { "code", "message", "details"? } }
 *
 * One envelope means the frontend needs exactly one response handler.
 */
export function sendSuccess<T>(
  res: Response,
  data: T,
  status = 200,
  meta?: Record<string, unknown>,
): void {
  res.status(status).json({ success: true, data, ...(meta ? { meta } : {}) });
}

/**
 * Validates untrusted input against a schema, raising a ValidationError that
 * the error middleware renders as a 422 with a field-by-field breakdown.
 *
 * Parsing at the edge of the application is what lets services below assume
 * their inputs are already well-formed.
 */
export function parseOrThrow<T>(schema: ZodType<T>, data: unknown): T {
  const result = schema.safeParse(data);

  if (!result.success) {
    throw new ValidationError('Validation failed', formatZodIssues(result.error));
  }

  return result.data;
}

function formatZodIssues(error: ZodError): Array<{ field: string; message: string }> {
  return error.issues.map((issue) => ({
    field: issue.path.join('.') || '(root)',
    message: issue.message,
  }));
}

import type { NextFunction, Request, RequestHandler, Response } from 'express';

/**
 * Express 4 does not catch rejected promises from async handlers, which would
 * leave a request hanging. Wrapping every async route in this forwards the
 * rejection to the error middleware instead.
 */
export function asyncHandler(
  handler: (req: Request, res: Response, next: NextFunction) => Promise<unknown>,
): RequestHandler {
  return (req, res, next) => {
    handler(req, res, next).catch(next);
  };
}

import type { Role } from './index.js';

/** The caller identity that `authenticate` attaches to the request. */
export interface AuthenticatedUser {
  id: string;
  email: string;
  role: Role;
}

declare global {
  namespace Express {
    interface Request {
      /** Present only on routes behind the `authenticate` middleware. */
      user?: AuthenticatedUser;
    }
  }
}

import type { RequestHandler } from 'express';
import { ForbiddenError, UnauthorizedError } from '../utils/errors.js';
import { verifyAccessToken } from '../utils/token.js';
import type { Role } from '../types/index.js';

/**
 * Verifies the `Authorization: Bearer <jwt>` header and attaches the caller to
 * the request. Routes that need an identity mount this; nothing else in the
 * codebase parses the header.
 */
export const authenticate: RequestHandler = (req, _res, next) => {
  const header = req.header('authorization');

  if (!header) {
    return next(new UnauthorizedError('Missing Authorization header'));
  }

  const [scheme, token] = header.split(' ');

  if (scheme?.toLowerCase() !== 'bearer' || !token) {
    return next(new UnauthorizedError('Expected an Authorization header of the form "Bearer <token>"'));
  }

  try {
    const payload = verifyAccessToken(token);
    req.user = { id: payload.sub, email: payload.email, role: payload.role };
    return next();
  } catch (error) {
    return next(error);
  }
};

/**
 * Restricts a route to the given roles. Must be mounted after `authenticate`.
 *
 * Kept separate from authentication so "who are you" and "may you do this"
 * stay independent concerns - a route can require a login without caring
 * about the role, and the admin rule is declared once and reused.
 */
export function requireRole(...roles: Role[]): RequestHandler {
  return (req, _res, next) => {
    if (!req.user) {
      return next(new UnauthorizedError('Authentication required'));
    }

    if (!roles.includes(req.user.role)) {
      return next(new ForbiddenError(`This action requires the ${roles.join(' or ')} role`));
    }

    return next();
  };
}

/** Convenience alias for the common case. */
export const requireAdmin = requireRole('ADMIN');

import type { ErrorRequestHandler, RequestHandler } from 'express';
import { getEnv } from '../config/env.js';
import { AppError, NotFoundError } from '../utils/errors.js';

/** Terminal 404 handler: anything that fell through the router. */
export const notFoundHandler: RequestHandler = (req, _res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.originalUrl}`));
};

/**
 * The single place where an error becomes an HTTP response.
 *
 * Known AppErrors keep their status and message. Everything else is treated
 * as a bug: it is logged server-side and reported as a generic 500, so stack
 * traces and SQL never reach the client.
 */
export const errorHandler: ErrorRequestHandler = (error, _req, res, _next) => {
  if (error instanceof AppError) {
    res.status(error.statusCode).json({
      success: false,
      error: {
        code: error.code,
        message: error.message,
        ...(error.details !== undefined ? { details: error.details } : {}),
      },
    });
    return;
  }

  // body-parser raises this for a malformed JSON payload.
  if (error instanceof SyntaxError && 'body' in error) {
    res.status(400).json({
      success: false,
      error: { code: 'MALFORMED_JSON', message: 'Request body is not valid JSON' },
    });
    return;
  }

  if (getEnv().NODE_ENV !== 'test') {
    console.error('[unhandled error]', error);
  }

  res.status(500).json({
    success: false,
    error: { code: 'INTERNAL_ERROR', message: 'Something went wrong on our side' },
  });
};

import { z } from 'zod';

/**
 * Request shapes for the auth endpoints.
 *
 * `strip` (Zod's default) drops unknown keys, which is why a client cannot
 * sneak `role: "ADMIN"` into a registration payload.
 */
export const registerSchema = z.object({
  name: z
    .string({ required_error: 'Name is required' })
    .trim()
    .min(2, 'Name must be at least 2 characters')
    .max(80, 'Name must be at most 80 characters'),
  email: z
    .string({ required_error: 'Email is required' })
    .trim()
    .email('Must be a valid email address')
    .max(255),
  password: z
    .string({ required_error: 'Password is required' })
    .min(8, 'Password must be at least 8 characters')
    .max(128, 'Password must be at most 128 characters'),
});

export const loginSchema = z.object({
  email: z.string({ required_error: 'Email is required' }).trim().email('Must be a valid email address'),
  password: z.string({ required_error: 'Password is required' }).min(1, 'Password is required'),
});

export type RegisterBody = z.infer<typeof registerSchema>;
export type LoginBody = z.infer<typeof loginSchema>;

import type { Request, Response } from 'express';
import type { AuthService } from '../services/authService.js';
import type { UserRepository } from '../repositories/userRepository.js';
import { loginSchema, registerSchema } from '../validation/authSchemas.js';
import { parseOrThrow, sendSuccess } from '../utils/http.js';
import { UnauthorizedError } from '../utils/errors.js';

/**
 * HTTP adapter for authentication.
 *
 * Controllers only translate: parse and validate input, call a service, shape
 * the response. No business rules live here, which is what keeps the service
 * layer reusable and independently testable.
 */
export class AuthController {
  constructor(
    private readonly authService: AuthService,
    private readonly users: UserRepository,
  ) {}

  register = async (req: Request, res: Response): Promise<void> => {
    const body = parseOrThrow(registerSchema, req.body);
    const result = await this.authService.register(body);

    sendSuccess(res, result, 201);
  };

  login = async (req: Request, res: Response): Promise<void> => {
    const body = parseOrThrow(loginSchema, req.body);
    const result = await this.authService.login(body);

    sendSuccess(res, result);
  };

  /** Lets the frontend restore a session from a stored token on page load. */
  me = async (req: Request, res: Response): Promise<void> => {
    const user = req.user ? this.users.findById(req.user.id) : null;

    if (!user) {
      throw new UnauthorizedError('This account no longer exists');
    }

    sendSuccess(res, { user });
  };
}

import type { Database } from 'better-sqlite3';
import { UserRepository } from './repositories/userRepository.js';
import { AuthService } from './services/authService.js';
import { AuthController } from './controllers/authController.js';

/**
 * Composition root.
 *
 * Wiring happens exactly once, here, from a single database handle. Every
 * class below receives its collaborators through its constructor, so no module
 * reaches for a global - and a test can build the whole graph against a
 * throwaway database by calling this with a different handle.
 */
export interface Container {
  authController: AuthController;
  userRepository: UserRepository;
}

export function buildContainer(db: Database): Container {
  const userRepository = new UserRepository(db);
  const authService = new AuthService(userRepository);

  return {
    userRepository,
    authController: new AuthController(authService, userRepository),
  };
}

import { Router } from 'express';
import type { AuthController } from '../controllers/authController.js';
import { authenticate } from '../middleware/authenticate.js';
import { asyncHandler } from '../utils/asyncHandler.js';

/** POST /register, POST /login (public) and GET /me (protected). */
export function createAuthRouter(controller: AuthController): Router {
  const router = Router();

  router.post('/register', asyncHandler(controller.register));
  router.post('/login', asyncHandler(controller.login));
  router.get('/me', authenticate, asyncHandler(controller.me));

  return router;
}

import { Router } from 'express';
import type { Container } from '../container.js';
import { createAuthRouter } from './authRoutes.js';
import { sendSuccess } from '../utils/http.js';

/** Mounts every feature router under /api. */
export function createApiRouter(container: Container): Router {
  const router = Router();

  router.get('/health', (_req, res) => {
    sendSuccess(res, { status: 'ok', timestamp: new Date().toISOString() });
  });

  router.use('/auth', createAuthRouter(container.authController));

  return router;
}

import cors from 'cors';
import express, { type Express } from 'express';
import type { Database } from 'better-sqlite3';
import { getEnv } from './config/env.js';
import { buildContainer } from './container.js';
import { createApiRouter } from './routes/index.js';
import { errorHandler, notFoundHandler } from './middleware/errorHandler.js';

/**
 * Builds the Express application around a database handle.
 *
 * Taking the database as an argument (rather than opening one inside) is what
 * lets the integration suite run the real app against a throwaway file, and
 * would let a future worker process share the same wiring.
 */
export function createApp(db: Database): Express {
  const env = getEnv();
  const app = express();

  app.disable('x-powered-by');
  app.use(cors({ origin: env.CORS_ORIGIN === '*' ? true : env.CORS_ORIGIN.split(',') }));
  app.use(express.json({ limit: '100kb' }));

  app.use('/api', createApiRouter(buildContainer(db)));

  // Order matters: unmatched routes first, then the error translator last.
  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}

import { createApp } from './app.js';
import { getEnv } from './config/env.js';
import { openDatabase } from './db/index.js';

/** Process entry point: open the database, start listening, shut down cleanly. */
function main(): void {
  const env = getEnv();
  const db = openDatabase(env.DATABASE_PATH);
  const app = createApp(db);

  const server = app.listen(env.PORT, () => {
    console.log(`API listening on http://localhost:${env.PORT} (${env.NODE_ENV})`);
    console.log(`Database: ${env.DATABASE_PATH}`);
  });

  const shutdown = (signal: string) => () => {
    console.log(`\n${signal} received, shutting down`);
    server.close(() => {
      db.close();
      process.exit(0);
    });
  };

  process.on('SIGINT', shutdown('SIGINT'));
  process.on('SIGTERM', shutdown('SIGTERM'));
}

main();

