import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type { Database } from 'better-sqlite3';
import { createTestDatabase } from '../helpers/testDb.js';
import { VehicleRepository } from '../../src/repositories/vehicleRepository.js';
import { PurchaseRepository } from '../../src/repositories/purchaseRepository.js';
import { VehicleService } from '../../src/services/vehicleService.js';
import { InventoryService } from '../../src/services/inventoryService.js';
import { createTransactionRunner } from '../../src/db/transaction.js';
import { BadRequestError, ConflictError, NotFoundError } from '../../src/utils/errors.js';
import type { Vehicle } from '../../src/types/index.js';

describe('InventoryService', () => {
  let db: Database;
  let cleanup: () => void;
  let vehicles: VehicleService;
  let purchases: PurchaseRepository;
  let inventory: InventoryService;
  let vehicle: Vehicle;
  let buyerId: string;

  beforeEach(() => {
    ({ db, cleanup } = createTestDatabase());

    const vehicleRepository = new VehicleRepository(db);
    purchases = new PurchaseRepository(db);
    vehicles = new VehicleService(vehicleRepository);
    inventory = new InventoryService(vehicleRepository, purchases, createTransactionRunner(db));

    vehicle = vehicles.create({
      make: 'Toyota',
      model: 'Corolla',
      category: 'SEDAN',
      year: 2022,
      price: 21_500,
      quantity: 3,
    });

    buyerId = 'buyer-1';
    db.prepare(
      'INSERT INTO users (id, name, email, password_hash, role) VALUES (?, ?, ?, ?, ?)',
    ).run(buyerId, 'Casey', 'casey@example.com', 'hash', 'CUSTOMER');
  });

  afterEach(() => cleanup());

  describe('purchase', () => {
    it('decreases the stock by the purchased quantity', () => {
      const result = inventory.purchase(vehicle.id, buyerId, 2);

      expect(result.vehicle.quantity).toBe(1);
      expect(vehicles.findById(vehicle.id).quantity).toBe(1);
    });

    it('defaults to buying one', () => {
      expect(inventory.purchase(vehicle.id, buyerId).vehicle.quantity).toBe(2);
    });

    it('records the purchase in the ledger with the price paid', () => {
      const result = inventory.purchase(vehicle.id, buyerId, 2);

      expect(result.purchase).toMatchObject({
        vehicleId: vehicle.id,
        userId: buyerId,
        quantity: 2,
        unitPrice: 21_500,
        totalPrice: 43_000,
      });

      const history = purchases.findByUser(buyerId);
      expect(history).toHaveLength(1);
      expect(history[0]?.totalPrice).toBe(43_000);
    });

    it('keeps the price paid even if the listing price changes later', () => {
      inventory.purchase(vehicle.id, buyerId, 1);
      vehicles.update(vehicle.id, { price: 25_000 });

      expect(purchases.findByUser(buyerId)[0]?.unitPrice).toBe(21_500);
    });

    it('allows buying the entire remaining stock', () => {
      expect(inventory.purchase(vehicle.id, buyerId, 3).vehicle.quantity).toBe(0);
    });

    it('refuses to buy more than is in stock', () => {
      expect(() => inventory.purchase(vehicle.id, buyerId, 4)).toThrow(ConflictError);
      expect(vehicles.findById(vehicle.id).quantity).toBe(3);
    });

    it('refuses to buy a sold-out vehicle', () => {
      inventory.purchase(vehicle.id, buyerId, 3);

      expect(() => inventory.purchase(vehicle.id, buyerId, 1)).toThrow(/out of stock/i);
    });

    it('writes no ledger row when the purchase is refused', () => {
      expect(() => inventory.purchase(vehicle.id, buyerId, 99)).toThrow(ConflictError);
      expect(purchases.findByUser(buyerId)).toHaveLength(0);
    });

    it('never lets stock go negative, however many buyers compete for it', () => {
      // Two buyers both try for the last three cars; only the first can win.
      inventory.purchase(vehicle.id, buyerId, 3);

      expect(() => inventory.purchase(vehicle.id, buyerId, 1)).toThrow(ConflictError);
      expect(vehicles.findById(vehicle.id).quantity).toBe(0);
    });

    it('rejects a zero or negative quantity', () => {
      expect(() => inventory.purchase(vehicle.id, buyerId, 0)).toThrow(BadRequestError);
      expect(() => inventory.purchase(vehicle.id, buyerId, -1)).toThrow(BadRequestError);
    });

    it('rejects a fractional quantity', () => {
      expect(() => inventory.purchase(vehicle.id, buyerId, 1.5)).toThrow(BadRequestError);
    });

    it('throws NotFoundError for an unknown vehicle', () => {
      expect(() => inventory.purchase('no-such-car', buyerId, 1)).toThrow(NotFoundError);
    });
  });

  describe('restock', () => {
    it('increases the stock', () => {
      expect(inventory.restock(vehicle.id, 5).quantity).toBe(8);
    });

    it('brings a sold-out vehicle back on sale', () => {
      inventory.purchase(vehicle.id, buyerId, 3);

      const restocked = inventory.restock(vehicle.id, 2);

      expect(restocked.quantity).toBe(2);
      expect(() => inventory.purchase(vehicle.id, buyerId, 1)).not.toThrow();
    });

    it('rejects a zero or negative quantity', () => {
      expect(() => inventory.restock(vehicle.id, 0)).toThrow(BadRequestError);
      expect(() => inventory.restock(vehicle.id, -3)).toThrow(BadRequestError);
    });

    it('throws NotFoundError for an unknown vehicle', () => {
      expect(() => inventory.restock('no-such-car', 1)).toThrow(NotFoundError);
    });
  });

  describe('purchase history', () => {
    it('returns a buyer\'s purchases, newest first, with the vehicle attached', () => {
      const suv = vehicles.create({
        make: 'Toyota',
        model: 'RAV4',
        category: 'SUV',
        year: 2023,
        price: 32_000,
        quantity: 1,
      });

      inventory.purchase(vehicle.id, buyerId, 1);
      inventory.purchase(suv.id, buyerId, 1);

      const history = inventory.historyFor(buyerId);

      expect(history).toHaveLength(2);
      expect(history.map((entry) => entry.vehicle?.model)).toContain('RAV4');
    });

    it('returns an empty list for a buyer who has bought nothing', () => {
      expect(inventory.historyFor('someone-else')).toEqual([]);
    });
  });
});

import type { Database } from 'better-sqlite3';

/** Runs a unit of work atomically: either every statement lands, or none does. */
export type TransactionRunner = <T>(work: () => T) => T;

/**
 * Wraps better-sqlite3's transaction helper behind a tiny function type.
 *
 * Services take a TransactionRunner rather than the database itself, so they
 * can guarantee atomicity without ever seeing a SQL driver - and a test could
 * pass a pass-through function if it wanted to.
 */
export function createTransactionRunner(db: Database): TransactionRunner {
  return <T>(work: () => T): T => db.transaction(work)();
}

import type { Database } from 'better-sqlite3';
import type { Purchase, Vehicle } from '../types/index.js';

interface PurchaseRow {
  id: string;
  vehicle_id: string;
  user_id: string;
  quantity: number;
  unit_price: number;
  total_price: number;
  purchased_at: string;
}

/** A purchase joined with the vehicle it was for, for the "my purchases" view. */
export interface PurchaseWithVehicle extends Purchase {
  vehicle: Pick<Vehicle, 'id' | 'make' | 'model' | 'category' | 'year'> | null;
}

export interface CreatePurchaseRecord {
  id: string;
  vehicleId: string;
  userId: string;
  quantity: number;
  unitPrice: number;
  totalPrice: number;
}

/** The purchase ledger: an append-only record of stock leaving the lot. */
export class PurchaseRepository {
  constructor(private readonly db: Database) {}

  create(record: CreatePurchaseRecord): Purchase {
    this.db
      .prepare(
        `INSERT INTO purchases (id, vehicle_id, user_id, quantity, unit_price, total_price)
         VALUES (@id, @vehicleId, @userId, @quantity, @unitPrice, @totalPrice)`,
      )
      .run(record);

    const created = this.db
      .prepare<[string], PurchaseRow>('SELECT * FROM purchases WHERE id = ?')
      .get(record.id);

    if (!created) throw new Error(`Purchase ${record.id} vanished immediately after insert`);

    return toPurchase(created);
  }

  findByUser(userId: string): Purchase[] {
    return this.db
      .prepare<[string], PurchaseRow>(
        'SELECT * FROM purchases WHERE user_id = ? ORDER BY purchased_at DESC, rowid DESC',
      )
      .all(userId)
      .map(toPurchase);
  }

  /**
   * History with the vehicle details attached.
   *
   * LEFT JOIN, not JOIN: a vehicle may have been delisted since, and a buyer
   * should still see what they bought.
   */
  findByUserWithVehicle(userId: string): PurchaseWithVehicle[] {
    const rows = this.db
      .prepare<[string], PurchaseRow & {
        v_id: string | null;
        v_make: string | null;
        v_model: string | null;
        v_category: string | null;
        v_year: number | null;
      }>(
        `SELECT p.*,
                v.id       AS v_id,
                v.make     AS v_make,
                v.model    AS v_model,
                v.category AS v_category,
                v.year     AS v_year
           FROM purchases p
           LEFT JOIN vehicles v ON v.id = p.vehicle_id
          WHERE p.user_id = ?
          ORDER BY p.purchased_at DESC, p.rowid DESC`,
      )
      .all(userId);

    return rows.map((row) => ({
      ...toPurchase(row),
      vehicle:
        row.v_id && row.v_make && row.v_model && row.v_category && row.v_year !== null
          ? {
              id: row.v_id,
              make: row.v_make,
              model: row.v_model,
              category: row.v_category,
              year: row.v_year,
            }
          : null,
    }));
  }

  countForVehicle(vehicleId: string): number {
    const row = this.db
      .prepare<[string], { count: number }>(
        'SELECT COUNT(*) AS count FROM purchases WHERE vehicle_id = ?',
      )
      .get(vehicleId);

    return row?.count ?? 0;
  }
}

function toPurchase(row: PurchaseRow): Purchase {
  return {
    id: row.id,
    vehicleId: row.vehicle_id,
    userId: row.user_id,
    quantity: row.quantity,
    unitPrice: row.unit_price,
    totalPrice: row.total_price,
    purchasedAt: row.purchased_at,
  };
}

import { randomUUID } from 'node:crypto';
import type { TransactionRunner } from '../db/transaction.js';
import type {
  PurchaseRepository,
  PurchaseWithVehicle,
} from '../repositories/purchaseRepository.js';
import type { VehicleRepository } from '../repositories/vehicleRepository.js';
import type { Purchase, Vehicle } from '../types/index.js';
import { BadRequestError, ConflictError, NotFoundError } from '../utils/errors.js';

export interface PurchaseResult {
  purchase: Purchase;
  vehicle: Vehicle;
}

/**
 * Stock movements.
 *
 * Separate from VehicleService on purpose: that class owns what a listing is,
 * this one owns how stock moves and keeps the ledger honest. The two have
 * different reasons to change, so they are different classes.
 */
export class InventoryService {
  constructor(
    private readonly vehicles: VehicleRepository,
    private readonly purchases: PurchaseRepository,
    private readonly transaction: TransactionRunner,
  ) {}

  /**
   * Sells `quantity` units of a vehicle to a user.
   *
   * The decrement and the ledger entry run in one transaction, and the stock
   * guard is part of the UPDATE's WHERE clause rather than a separate read.
   * That combination is what makes overselling impossible: if two buyers race
   * for the last car, exactly one UPDATE reports a changed row.
   */
  purchase(vehicleId: string, userId: string, quantity = 1): PurchaseResult {
    assertPositiveWholeNumber(quantity, 'Purchase quantity');

    const vehicle = this.requireVehicle(vehicleId);

    if (vehicle.quantity === 0) {
      throw new ConflictError(
        `${vehicle.year} ${vehicle.make} ${vehicle.model} is out of stock`,
      );
    }

    if (vehicle.quantity < quantity) {
      throw new ConflictError(
        `Only ${vehicle.quantity} left in stock, cannot purchase ${quantity}`,
      );
    }

    return this.transaction(() => {
      if (!this.vehicles.decrementStock(vehicleId, quantity)) {
        // Lost a race against another buyer between the read and the update.
        throw new ConflictError('That vehicle was just sold - please refresh and try again');
      }

      const purchase = this.purchases.create({
        id: randomUUID(),
        vehicleId,
        userId,
        quantity,
        // Snapshot the price: the ledger records what was paid, not what the
        // listing happens to cost today.
        unitPrice: vehicle.price,
        totalPrice: round2(vehicle.price * quantity),
      });

      const updated = this.vehicles.findById(vehicleId);
      if (!updated) throw new NotFoundError(`No vehicle with id ${vehicleId}`);

      return { purchase, vehicle: updated };
    });
  }

  /** Adds stock back onto the lot (admin only, enforced at the route). */
  restock(vehicleId: string, quantity: number): Vehicle {
    assertPositiveWholeNumber(quantity, 'Restock quantity');

    this.requireVehicle(vehicleId);

    if (!this.vehicles.incrementStock(vehicleId, quantity)) {
      throw new NotFoundError(`No vehicle with id ${vehicleId}`);
    }

    const updated = this.vehicles.findById(vehicleId);
    if (!updated) throw new NotFoundError(`No vehicle with id ${vehicleId}`);

    return updated;
  }

  historyFor(userId: string): PurchaseWithVehicle[] {
    return this.purchases.findByUserWithVehicle(userId);
  }

  private requireVehicle(vehicleId: string): Vehicle {
    const vehicle = this.vehicles.findById(vehicleId);
    if (!vehicle) throw new NotFoundError(`No vehicle with id ${vehicleId}`);

    return vehicle;
  }
}

function assertPositiveWholeNumber(value: number, label: string): void {
  if (!Number.isInteger(value) || value < 1) {
    throw new BadRequestError(`${label} must be a whole number of at least 1`);
  }
}

/** Money is stored as a REAL, so round to cents to avoid float drift. */
function round2(value: number): number {
  return Math.round(value * 100) / 100;
}

