import type { Request, Response } from 'express';
import type { VehicleService } from '../services/vehicleService.js';
import type { InventoryService } from '../services/inventoryService.js';
import { parseOrThrow, sendSuccess } from '../utils/http.js';
import { UnauthorizedError } from '../utils/errors.js';
import {
  createVehicleSchema,
  purchaseSchema,
  restockSchema,
  searchVehiclesSchema,
  updateVehicleSchema,
} from '../validation/vehicleSchemas.js';

/**
 * HTTP adapter for the catalogue and the inventory.
 *
 * Authorisation is not checked here: the router declares which roles may
 * reach each handler, so the rule is visible in one place rather than buried
 * in a dozen `if (user.role !== ...)` branches.
 */
export class VehicleController {
  constructor(
    private readonly vehicles: VehicleService,
    private readonly inventory: InventoryService,
  ) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const body = parseOrThrow(createVehicleSchema, req.body);

    sendSuccess(res, { vehicle: this.vehicles.create(body) }, 201);
  };

  /**
   * Backs both GET /vehicles and GET /vehicles/search: listing is just a
   * search with no filters, so there is one code path instead of two.
   */
  search = async (req: Request, res: Response): Promise<void> => {
    const query = parseOrThrow(searchVehiclesSchema, req.query);
    const { items, ...meta } = this.vehicles.search(query);

    sendSuccess(res, { vehicles: items }, 200, { ...meta, filters: query });
  };

  filters = async (_req: Request, res: Response): Promise<void> => {
    sendSuccess(res, this.vehicles.facets());
  };

  findOne = async (req: Request, res: Response): Promise<void> => {
    sendSuccess(res, { vehicle: this.vehicles.findById(requireId(req)) });
  };

  update = async (req: Request, res: Response): Promise<void> => {
    const patch = parseOrThrow(updateVehicleSchema, req.body);

    sendSuccess(res, { vehicle: this.vehicles.update(requireId(req), patch) });
  };

  remove = async (req: Request, res: Response): Promise<void> => {
    this.vehicles.remove(requireId(req));

    // 204: the deletion succeeded and there is nothing meaningful to return.
    res.status(204).send();
  };

  purchase = async (req: Request, res: Response): Promise<void> => {
    const { quantity } = parseOrThrow(purchaseSchema, req.body ?? {});
    const buyer = requireUser(req);

    sendSuccess(res, this.inventory.purchase(requireId(req), buyer.id, quantity), 201);
  };

  restock = async (req: Request, res: Response): Promise<void> => {
    const { quantity } = parseOrThrow(restockSchema, req.body);

    sendSuccess(res, { vehicle: this.inventory.restock(requireId(req), quantity) });
  };

  myPurchases = async (req: Request, res: Response): Promise<void> => {
    sendSuccess(res, { purchases: this.inventory.historyFor(requireUser(req).id) });
  };
}

/** Express guarantees the param exists for these routes; this satisfies the types. */
function requireId(req: Request): string {
  return req.params.id ?? '';
}

function requireUser(req: Request): { id: string } {
  if (!req.user) throw new UnauthorizedError('Authentication required');

  return req.user;
}

import { Router } from 'express';
import type { VehicleController } from '../controllers/vehicleController.js';
import { authenticate, requireAdmin } from '../middleware/authenticate.js';
import { asyncHandler } from '../utils/asyncHandler.js';

/**
 * Every vehicle route requires a signed-in user; writes additionally require
 * an admin. Declaring it here keeps the whole permission model readable at a
 * glance, which is exactly what you want to be able to audit.
 */
export function createVehicleRouter(controller: VehicleController): Router {
  const router = Router();

  router.use(authenticate);

  // Literal paths must be declared before "/:id", or "search" would be
  // interpreted as a vehicle id.
  router.get('/search', asyncHandler(controller.search));
  router.get('/filters', asyncHandler(controller.filters));

  router.get('/', asyncHandler(controller.search));
  router.get('/:id', asyncHandler(controller.findOne));

  router.post('/', requireAdmin, asyncHandler(controller.create));
  router.put('/:id', requireAdmin, asyncHandler(controller.update));
  router.delete('/:id', requireAdmin, asyncHandler(controller.remove));

  // Anyone signed in may buy; only an admin may put stock back on the lot.
  router.post('/:id/purchase', asyncHandler(controller.purchase));
  router.post('/:id/restock', requireAdmin, asyncHandler(controller.restock));

  return router;
}

/** GET /api/purchases/me - the signed-in user's own purchase history. */
export function createPurchaseRouter(controller: VehicleController): Router {
  const router = Router();

  router.use(authenticate);
  router.get('/me', asyncHandler(controller.myPurchases));

  return router;
}

import type { Database } from 'better-sqlite3';
import { UserRepository } from './repositories/userRepository.js';
import { VehicleRepository } from './repositories/vehicleRepository.js';
import { PurchaseRepository } from './repositories/purchaseRepository.js';
import { AuthService } from './services/authService.js';
import { VehicleService } from './services/vehicleService.js';
import { InventoryService } from './services/inventoryService.js';
import { AuthController } from './controllers/authController.js';
import { VehicleController } from './controllers/vehicleController.js';
import { createTransactionRunner } from './db/transaction.js';

/**
 * Composition root.
 *
 * Wiring happens exactly once, here, from a single database handle. Every
 * class below receives its collaborators through its constructor, so no module
 * reaches for a global - and a test can build the whole graph against a
 * throwaway database by calling this with a different handle.
 */
export interface Container {
  authController: AuthController;
  vehicleController: VehicleController;
  userRepository: UserRepository;
}

export function buildContainer(db: Database): Container {
  const transaction = createTransactionRunner(db);

  const userRepository = new UserRepository(db);
  const vehicleRepository = new VehicleRepository(db);
  const purchaseRepository = new PurchaseRepository(db);

  const authService = new AuthService(userRepository);
  const vehicleService = new VehicleService(vehicleRepository);
  const inventoryService = new InventoryService(
    vehicleRepository,
    purchaseRepository,
    transaction,
  );

  return {
    userRepository,
    authController: new AuthController(authService, userRepository),
    vehicleController: new VehicleController(vehicleService, inventoryService),
  };
}

import { Router } from 'express';
import type { Container } from '../container.js';
import { createAuthRouter } from './authRoutes.js';
import { createPurchaseRouter, createVehicleRouter } from './vehicleRoutes.js';
import { sendSuccess } from '../utils/http.js';

/** Mounts every feature router under /api. */
export function createApiRouter(container: Container): Router {
  const router = Router();

  router.get('/health', (_req, res) => {
    sendSuccess(res, { status: 'ok', timestamp: new Date().toISOString() });
  });

  router.use('/auth', createAuthRouter(container.authController));
  router.use('/vehicles', createVehicleRouter(container.vehicleController));
  router.use('/purchases', createPurchaseRouter(container.vehicleController));

  return router;
}

