  --font-sans: 'Inter', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-display: 'Inter', ui-sans-serif, system-ui, sans-serif;

  --radius-card: 1rem;

  --shadow-glow: 0 0 0 1px rgb(245 158 11 / 0.25), 0 8px 30px -8px rgb(245 158 11 / 0.35);
  --shadow-lift: 0 18px 40px -24px rgb(0 0 0 / 0.9);

  --animate-fade-up: fade-up 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-fade-in: fade-in 0.3s ease-out both;
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
