}

@layer base {
  html {
    scroll-behavior: smooth;
    color-scheme: dark;
  }

  body {
    @apply bg-ink-950 text-ink-100 font-sans antialiased;
    /* A faint warm glow behind the content, so the page is not flat black. */
    background-image:
