        </div>
      </div>
    </article>
  );
}

/** Stock level as a colour-coded chip: sold out, last one, or a count. */
function StockBadge({ quantity }: { quantity: number }) {
  const tone =
    quantity === 0
      ? 'border-danger-500/40 bg-danger-500/15 text-danger-300'
      : quantity <= 2
        ? 'border-brand-400/40 bg-brand-400/15 text-brand-300'
        : 'border-success-500/40 bg-success-500/15 text-success-300';

  const label = quantity === 0 ? 'Sold out' : quantity === 1 ? '1 left' : `${quantity} in stock`;

  return (
    <span
      className={`absolute right-3 top-3 rounded-full border px-2.5 py-1 text-[11px] font-semibold backdrop-blur-sm ${tone}`}
    >
      {label}
    </span>
  );
}

import { useEffect, useState } from 'react';
import { SelectField, TextField } from '../ui/Field.js';
import { Button } from '../ui/Button.js';
import { formatCategory } from '../../lib/format.js';
import type { VehicleFilters as Filters } from '../../types/index.js';

interface VehicleFiltersProps {
  value: Filters;
  makes: string[];
  categories: string[];
  resultCount: number;
  onChange: (filters: Filters) => void;
}

/**
 * The search and filter bar.
 *
 * The free-text box is debounced so typing does not fire a request per
 * keystroke; the selects apply immediately, because a dropdown choice is a
 * deliberate single action.
 */
export function VehicleFilters({
  value,
  makes,
  categories,
  resultCount,
  onChange,
}: VehicleFiltersProps) {
  const [query, setQuery] = useState(value.q ?? '');

  // Keep the input in step when filters are cleared from outside.
  useEffect(() => {
    setQuery(value.q ?? '');
  }, [value.q]);

  useEffect(() => {
    if (query === (value.q ?? '')) return;

    const timer = window.setTimeout(() => onChange({ ...value, q: query, page: 1 }), 300);
    return () => window.clearTimeout(timer);
  }, [query, value, onChange]);

  const update = (patch: Filters) => onChange({ ...value, ...patch, page: 1 });

  const activeCount = [
    value.make,
    value.category,
    value.minPrice,
    value.maxPrice,
    value.availableOnly ? 'yes' : undefined,
    value.q,
  ].filter(Boolean).length;

  return (
    <section className="surface p-5" aria-label="Search and filter vehicles">
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <div className="sm:col-span-2 lg:col-span-1">
          <TextField
            label="Search"
            type="search"
            placeholder="Make, model, keyword..."
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
        </div>

        <SelectField
          label="Make"
          value={value.make ?? ''}
          onChange={(event) => update({ make: event.target.value || undefined })}
        >
          <option value="">All makes</option>
          {makes.map((make) => (
            <option key={make} value={make}>
              {make}
            </option>
          ))}
        </SelectField>

        <SelectField
          label="Category"
          value={value.category ?? ''}
          onChange={(event) => update({ category: event.target.value || undefined })}
        >
          <option value="">All categories</option>
          {categories.map((category) => (
            <option key={category} value={category}>
              {formatCategory(category)}
            </option>
          ))}
        </SelectField>

        <SelectField
          label="Sort by"
          value={value.sort ?? 'newest'}
          onChange={(event) => update({ sort: event.target.value as Filters['sort'] })}
        >
          <option value="newest">Newest listings</option>
          <option value="price_asc">Price: low to high</option>
          <option value="price_desc">Price: high to low</option>
          <option value="year_desc">Model year: newest</option>
        </SelectField>

        <TextField
          label="Min price"
          type="number"
          min={0}
          step={500}
          placeholder="0"
          value={value.minPrice ?? ''}
          onChange={(event) =>
            update({ minPrice: event.target.value ? Number(event.target.value) : undefined })
          }
        />

        <TextField
          label="Max price"
          type="number"
          min={0}
          step={500}
          placeholder="Any"
          value={value.maxPrice ?? ''}
          onChange={(event) =>
            update({ maxPrice: event.target.value ? Number(event.target.value) : undefined })
          }
        />

        <label className="flex cursor-pointer select-none items-end gap-2.5 pb-2.5 text-sm text-ink-200">
          <input
            type="checkbox"
            checked: never
            className="h-4 w-4 rounded border-ink-500 bg-ink-850 text-brand-500 focus:ring-brand-400/40"
          />
          In stock only
        </label>
      </div>

      <div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-ink-700/60 pt-4">
        <p className="text-sm text-ink-400">
          <span className="font-semibold text-ink-100">{resultCount}</span>{' '}
          {resultCount === 1 ? 'vehicle' : 'vehicles'} found
          {activeCount > 0 ? ` with ${activeCount} filter${activeCount === 1 ? '' : 's'} applied` : ''}
        </p>

        {activeCount > 0 ? (
          <Button variant="ghost" size="sm" onClick={() => onChange({ sort: 'newest', page: 1 })}>
            Clear filters
          </Button>
        ) : null}
      </div>
    </section>
  );
}

import { useEffect, useState } from 'react';
import { Modal } from '../ui/Modal.js';
import { Button } from '../ui/Button.js';
import { SelectField, TextAreaField, TextField } from '../ui/Field.js';
import { formatCategory } from '../../lib/format.js';
import { VEHICLE_CATEGORIES, type Vehicle, type VehicleInput } from '../../types/index.js';

interface VehicleFormModalProps {
  open: boolean;
  /** Present when editing, absent when adding. */
  vehicle?: Vehicle | null;
  saving: boolean;
  fieldErrors: Record<string, string>;
  onClose: () => void;
  onSubmit: (input: VehicleInput) => void;
}

type FormState = {
  make: string;
  model: string;
  category: string;
  year: string;
  price: string;
  quantity: string;
  description: string;
};

const EMPTY_FORM: FormState = {
  make: '',
  model: '',
  category: 'SEDAN',
  year: String(new Date().getFullYear()),
  price: '',
  quantity: '1',
  description: '',
};

/**
 * One form for both adding and editing, since the fields are identical and
 * two near-duplicate forms would drift apart. Server-side validation errors
 * are shown against the field they belong to.
 */
export function VehicleFormModal({
  open,
  vehicle,
  saving,
  fieldErrors,
  onClose,
  onSubmit,
}: VehicleFormModalProps) {
  const [form, setForm] = useState<FormState>(EMPTY_FORM);

  // Reload the form whenever the dialog opens for a different vehicle.
  useEffect(() => {
    if (!open) return;

    setForm(
      vehicle
        ? {
            make: vehicle.make,
            model: vehicle.model,
            category: vehicle.category,
            year: String(vehicle.year),
            price: String(vehicle.price),
            quantity: String(vehicle.quantity),
            description: vehicle.description ?? '',
          }
        : EMPTY_FORM,
    );
  }, [open, vehicle]);

  const set = <K extends keyof FormState>(key: K, value: string) =>
    setForm((current) => ({ ...current, [key]: value }));

  const submit = (event: React.FormEvent) => {
    event.preventDefault();

    onSubmit({
      make: form.make.trim(),
      model: form.model.trim(),
      category: form.category,
      year: Number(form.year),
      price: Number(form.price),
      quantity: Number(form.quantity),
      description: form.description.trim() || null,
    });
  };

  return (
    <Modal
      open={open}
      title={vehicle ? `Edit ${vehicle.make} ${vehicle.model}` : 'Add a vehicle'}
      description={
        vehicle
          ? 'Update the listing. Only the fields you change are sent.'
          : 'List a new vehicle on the lot.'
      }
      onClose={onClose}
    >
      <form onSubmit={submit} className="space-y-4" noValidate>
        <div className="grid gap-4 sm:grid-cols-2">
          <TextField
            label="Make"
            value={form.make}
            onChange={(event) => set('make', event.target.value)}
            error={fieldErrors.make}
            placeholder="Toyota"
            required
          />
          <TextField
            label="Model"
            value={form.model}
            onChange={(event) => set('model', event.target.value)}
            error={fieldErrors.model}
            placeholder="Corolla"
            required
          />
          <SelectField
            label="Category"
            value={form.category}
            onChange={(event) => set('category', event.target.value)}
            error={fieldErrors.category}
          >
            {VEHICLE_CATEGORIES.map((category) => (
              <option key={category} value={category}>
                {formatCategory(category)}
              </option>
            ))}
          </SelectField>
          <TextField
            label="Model year"
            type="number"
            min={1900}
            value={form.year}
            onChange={(event) => set('year', event.target.value)}
            error={fieldErrors.year}
            required
          />
          <TextField
            label="Price (USD)"
            type="number"
            min={0}
            step={100}
            value={form.price}
            onChange={(event) => set('price', event.target.value)}
            error={fieldErrors.price}
            placeholder="21500"
            required
          />
          <TextField
            label="Quantity in stock"
            type="number"
            min={0}
            value={form.quantity}
            onChange={(event) => set('quantity', event.target.value)}
            error={fieldErrors.quantity}
            hint="Zero is allowed - the listing shows as sold out."
            required
          />
        </div>

        <TextAreaField
          label="Description"
          rows={3}
          value={form.description}
          onChange={(event) => set('description', event.target.value)}
          error={fieldErrors.description}
          placeholder="What makes this one worth a look?"
        />

        {fieldErrors['(root)'] ? (
          <p className="text-sm text-danger-300">{fieldErrors['(root)']}</p>
        ) : null}

        <div className="flex justify-end gap-3 pt-2">
          <Button type="button" variant="secondary" onClick={onClose} disabled={saving}>
            Cancel
          </Button>
          <Button type="submit" loading={saving}>
            {vehicle ? 'Save changes' : 'Add vehicle'}
          </Button>
        </div>
      </form>
    </Modal>
  );
}

