    return this.request<{ vehicle: Vehicle }>(`/vehicles/${id}`, { method: 'PUT', body: patch });
  }

  async deleteVehicle(id: string): Promise<void> {
    await this.request<null>(`/vehicles/${id}`, { method: 'DELETE' });
  }

