  private async requestWithMeta<T, M>(
    path: string,
    { method = 'GET', body, query, signal }: RequestOptions = {},
  ): Promise<{ data: T; meta: M }> {
    const token = this.getToken();

    const response = await fetch(`${this.baseUrl}${path}${buildQueryString(query)}`, {
      method,
      signal,
