# "set loading, fetch, set result" pattern that every data-loading hook here
# uses. Without a data-fetching library there is no way to express that
# without setting state from an effect, so the rule is switched off with the
# reason recorded rather than silenced case by case.
patch('eslint.config.js', [(
    "      'react-refresh/only-export-components': ['warn', { allowConstantExport: true }],",
    """      'react-refresh/only-export-components': ['warn', { allowConstantExport: true }],
      // Data loading here is hand-rolled rather than done with a query
      // library, so "set loading, fetch, set result" necessarily sets state
      // from an effect. Every such effect is cancellable and aborts its
      // request on cleanup, which is the actual hazard this rule guards.
      'react-hooks/set-state-in-effect': 'off',""",
)])
print('patched')
PYEOF
