import io

p = 'src/container.ts'
s = io.open(p, encoding='utf-8').read()
s = s.replace("import { VehicleController } from './controllers/vehicleController.js';",
              "import { VehicleController } from './controllers/vehicleController.js';\nimport { HealthController } from './controllers/healthController.js';")
s = s.replace("""export interface Container {
  authController: AuthController;
  vehicleController: VehicleController;
  userRepository: UserRepository;
}""",
"""export interface Container {
  authController: AuthController;
  vehicleController: VehicleController;
  healthController: HealthController;
  userRepository: UserRepository;
}""")
s = s.replace("""    vehicleController: new VehicleController(vehicleService, inventoryService),""",
              """    vehicleController: new VehicleController(vehicleService, inventoryService),
    healthController: new HealthController(db),""")
io.open(p, 'w', encoding='utf-8', newline='\n').write(s)

p = 'src/middleware/errorHandler.ts'
s = io.open(p, encoding='utf-8').read()
s = s.replace("""export const errorHandler: ErrorRequestHandler = (error, _req, res, _next) => {
  if (error instanceof AppError) {
    res.status(error.statusCode).json({
      success: false,
      error: {
        code: error.code,
        message: error.message,
        ...(error.details !== undefined ? { details: error.details } : {}),
      },
    });
    return;
  }

  // body-parser raises this for a malformed JSON payload.
  if (error instanceof SyntaxError && 'body' in error) {
    res.status(400).json({
      success: false,
      error: { code: 'MALFORMED_JSON', message: 'Request body is not valid JSON' },
    });
    return;
  }

  if (getEnv().NODE_ENV !== 'test') {
    console.error('[unhandled error]', error);
  }

  res.status(500).json({
    success: false,
    error: { code: 'INTERNAL_ERROR', message: 'Something went wrong on our side' },
  });
};""",
"""export const errorHandler: ErrorRequestHandler = (error, req, res, _next) => {
  // Every error body carries the request id, so a user can quote one string
  // in a bug report and it can be found in the logs.
  const requestId = req.id;

  if (error instanceof AppError) {
    res.status(error.statusCode).json({
      success: false,
      error: {
        code: error.code,
        message: error.message,
        ...(error.details !== undefined ? { details: error.details } : {}),
        requestId,
      },
    });
    return;
  }

  // body-parser raises these for a malformed or oversized payload.
  if (error instanceof SyntaxError && 'body' in error) {
    res.status(400).json({
      success: false,
      error: { code: 'MALFORMED_JSON', message: 'Request body is not valid JSON', requestId },
    });
    return;
  }

  if (isPayloadTooLarge(error)) {
    res.status(413).json({
      success: false,
      error: { code: 'PAYLOAD_TOO_LARGE', message: 'Request body is too large', requestId },
    });
    return;
  }

  if (getEnv().NODE_ENV !== 'test') {
    console.error(JSON.stringify({ level: 'error', requestId, message: String(error) }));
  }

  res.status(500).json({
    success: false,
    error: { code: 'INTERNAL_ERROR', message: 'Something went wrong on our side', requestId },
  });
};

/** body-parser marks an oversized body with `type: 'entity.too.large'`. */
function isPayloadTooLarge(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'type' in error &&
    (error as { type?: unknown }).type === 'entity.too.large'
  );
}""")
io.open(p, 'w', encoding='utf-8', newline='\n').write(s)
print('patched')
