const searchParams = [
  { name: 'q', in: 'query', schema: { type: 'string' }, description: 'Free text across make, model, category and description' },
  { name: 'make', in: 'query', schema: { type: 'string' }, description: 'Partial, case-insensitive' },
  { name: 'model', in: 'query', schema: { type: 'string' }, description: 'Partial, case-insensitive' },
  { name: 'category', in: 'query', schema: { type: 'string' }, description: 'Exact, case-insensitive' },
