    const response = await request(ctx.app).get('/api/openapi.json');

    expect(response.status).toBe(200);
    expect(response.body.openapi).toMatch(/^3\./);
    expect(response.body.info.title).toContain('Dealership');
    expect(Object.keys(response.body.paths).length).toBeGreaterThan(5);
  });

  it('serves a browsable UI', async () => {
    const response = await request(ctx.app).get('/api/docs/');

    expect(response.status).toBe(200);
    expect(response.text).toMatch(/swagger/i);
  });

  it('declares bearer authentication', () => {
    expect(openApiDocument.components.securitySchemes.bearerAuth).toMatchObject({
      type: 'http',
      scheme: 'bearer',
    });
  });

  it('documents the admin-only endpoints as such', () => {
    const adminOnly = [
      openApiDocument.paths['/vehicles'].post.summary,
      openApiDocument.paths['/vehicles/{id}'].put.summary,
      openApiDocument.paths['/vehicles/{id}'].delete.summary,
      openApiDocument.paths['/vehicles/{id}/restock'].post.summary,
    ];

    for (const summary of adminOnly) {
      expect(summary.toLowerCase()).toContain('admin');
    }
  });

  /**
   * The anti-drift test.
   *
   * A hand-written spec is worth having for the prose, but it rots the moment
   * a route is renamed. So every path and method the document claims is
   * actually called here: a documented endpoint that answers 404 means the
   * spec is lying, and fails the build.
   *
   * No credentials are sent, so 401 and 403 are perfectly good answers - the
   * only unacceptable one is "no such route".
   */
  it('documents only endpoints that really exist', async () => {
    const unroutable: string[] = [];
    let checked = 0;

    for (const [specPath, operations] of Object.entries(openApiDocument.paths)) {
      // An id that cannot exist: authentication runs before the lookup, so a
      // 401 still proves the route is wired up, and a 404 from a *routed*
      // endpoint would come with a JSON error code rather than Express's
      // "cannot GET" fallback.
      const url = `/api${specPath.replace('{id}', '11111111-1111-1111-1111-111111111111')}`;

      for (const method of Object.keys(operations)) {
        const response = await send(ctx.app, method, url);
        checked += 1;

        const routeIsMissing =
          response.status === 404 && response.body?.error?.message?.startsWith('Cannot ');

        if (routeIsMissing) unroutable.push(`${method.toUpperCase()} ${url}`);
      }
    }

    expect(unroutable, 'documented routes that do not exist').toEqual([]);
    expect(checked).toBeGreaterThan(10);
  });

  it('documents every route the API actually serves', () => {
    // The other direction: an endpoint that exists but is undocumented.
    const documented = new Set(Object.keys(openApiDocument.paths));

    const expected = [
      '/health',
      '/auth/register',
      '/auth/login',
      '/auth/me',
      '/vehicles',
      '/vehicles/search',
      '/vehicles/filters',
      '/vehicles/{id}',
      '/vehicles/{id}/purchase',
      '/vehicles/{id}/restock',
      '/purchases/me',
    ];

    for (const path of expected) {
      expect(documented, `${path} is not documented`).toContain(path);
    }
  });
});

