import { AuthProvider } from '../src/context/AuthProvider.js';
import { useAuth } from '../src/hooks/useAuth.js';
import { ProtectedRoute } from '../src/components/ProtectedRoute.js';

const TOKEN_KEY = 'apex-motors.token';

